        dims.t=1;dims.coils=0;dims.averages=0;dims.subSpecs=0;dims.extras=0;
    end

    %Now get the size of the data array:
    sz=size(fids);

    %Remove phase cycle for Philips data
    if isfield(hdr_ext, 'ProtocolName') && contains(hdr_ext.ProtocolName,'HBCD')
        undoPhaseCycle = 1;
    end
    if isfield(hdr_ext, 'Manufacturer') && strcmp(hdr_ext.Manufacturer,'Philips')  && undoPhaseCycle
        fids = fids .* repmat(conj(fids(1,:,:,:))./abs(fids(1,:,:,:)),[size(fids,1) 1]);
    end
    if isfield(hdr_ext, 'Manufacturer') && strcmp(hdr_ext.Manufacturer,'GE') && undoPhaseCycle 
        if hdr_ext.WaterSuppressed && hdr_ext.EchoTime == 0.080
            fids(:,:,2:2:end,:) = -fids(:,:,2:2:end,:);
        end
    end

    %Compared to NIfTI MRS, FID-A needs the conjugate
    fids = conj(fids);

    %Now take fft of time domain to get fid:
    specs=fftshift(fft(fids,[],dims.t),dims.t);

end



% Fill in additional FID-A format variables
% Nucleus (new field)
out.nucleus = hdr_ext.ResonantNucleus;
% Calculate B0 from spectrometer frequency depending on nucleus
% Gamma from Wikipedia article "Gyromagnetic ratio" (3 signif. digits)
for rr = 1:length(out.nucleus)
    switch strtrim(out.nucleus{rr})
        case '1H'
            gamma = 42.577;
        case '2H'
            gamma = 6.536;
        case '3HE'
    % Determine number of dynamics per NSA. It is not stored in the dynamics
    % field, but rather in extra attributes. Could be different for different
    % software versions, need to check!
    n_dyns = data.kspace_properties.number_of_extra_attribute_1_values;
    n_dyns_edit = n_dyns(1);
    %if n_mixes == 2
    %    n_dyns_water = n_dyns(2); % if second mix exists, it is water
    %end
    % Since dynamics are set globally on the exam card, this will be the same
    % for both - it will only be the true value for the water-suppressed mix

    % Determine number of data points per scan
    n_points = data.kspace_properties.F_resolution(1);

    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    % Start splitting the list of total scans into its parts:
    % Noise scans, water-suppressed scans, and water-unsuppressed scans.
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    % Noise scans have the data type 'NOI'
    isnoise = strcmp(data.typ,'NOI');
    fids_noise = cell2mat(data.complexdata(isnoise));
    n_av_noise = size(fids_noise,1) ./ n_coils;

    % Separate the water-suppressed from the water-unsuppressed scans.
    % Water-suppressed scans have the data type 'STD' and mix index 0:
    isedit = strcmp(data.typ,'STD') & (data.mix == 0);
    fids_edit = cell2mat(data.complexdata(isedit));
    % Reshape the water-suppressed data
    fids_edit = reshape(fids_edit,[n_coils n_av_edit*n_dyns_edit n_points]);

    %Permute order of the data to match MRSCont structure
    fids_edit = permute(fids_edit,[3 1 2]);

    % Phase by multiplying with normalized complex conjugate of first point
%     if ~MRS_struct.p.PRIAM
%         % Don't do this when using SENSE reconstruction!
%         conj_norm = conj(fids_edit(:,:,1)) ./ abs(conj(fids_edit(:,:,1)));
%         fids_edit_ph = fids_edit .* repmat(conj_norm, [1 1 n_points]);
%     else
%         fids_edit_ph = fids_edit;
%     end
    fids_edit_ph = fids_edit;


    % Water-unsuppressed scans have the data type 'STD' and mix index 1:
    if n_mixes == 2
        iswater = strcmp(data.typ,'STD') & (data.mix == 1);
        fids_water = cell2mat(data.complexdata(iswater));

        % Reshape the water-unsuppressed data
        fids_water = reshape(fids_water,[n_coils n_av_water n_points]);

        % Phase by multiplying with normalized complex conjugate of first point
%         if ~MRS_struct.p.PRIAM
%             % Don't do this when using SENSE reconstruction!
%             conj_norm = conj(fids_water(:,:,1)) ./ abs(conj(fids_water(:,:,1)));
%             fids_water_ph = fids_water .* repmat(conj_norm, [1 1 n_points]);
%         else
%             fids_water_ph = fids_water;
%         end
        %Permute order of the data to match MRSCont structure
        fids_water = permute(fids_water,[3 1 2]);
        fids_water_ph = fids_water;        


    end

    % Perform coil combination if not PRIAM
%     if ~MRS_struct.p.PRIAM
%         if n_mixes == 2

% op_ampScale.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_ampScale(in,A);
% 
% DESCRIPTION:
% Scale the amplitude of a spectrum by factor A.
% 
% INPUTS:
% in    = input data in matlab structure format
% A     = Amplitude scaling factor.
%
% OUTPUTS:
% out   = Output following amplitude scaling.  

function out=op_ampScale(in,A);

sz_A = length(A);
out=in;
if sz_A == 1
    out.specs=in.specs*A;
    out.fids=in.fids*A;
else

    if in.dims.averages==0   
        for ss = 1 : out.sz(end)
            out.specs(:,ss)=in.specs(:,ss)*A(ss);
            out.fids(:,ss)=in.fids(:,ss)*A(ss);
        end
    else
        for ss = 1 : out.sz(end)
            out.specs(:,:,ss)=in.specs(:,:,ss)*A(ss);
            out.fids(:,:,ss)=in.fids(:,:,ss)*A(ss);
        end
    end
end

% op_freqrange.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_freqrange(in,ppmmin,ppmmax);
% 
% DESCRIPTION:
% Output only a specified frequency range of the input spectrum.
% 
% INPUTS:
% in         = input data in matlab structure format.
% ppmmin     = minimum extent of frequency range in ppm.
% ppmmax     = maximum extent of frequency range in ppm.
%
% OUTPUTS:
% out        = Output following frequency range selection.

function out=op_freqrange(in,ppmmin,ppmmax,npoints);
if nargin < 4
    npoints = 0;
end
%Calculate Specs using fft
fullspecs=fftshift(fft(in.fids,[],in.dims.t),in.dims.t);

%now take only the specified range of the spectrum
specs=fullspecs(in.ppm>=ppmmin & in.ppm<=ppmmax,:,:,:,:);

if npoints ~= 0 && npoints > length(specs)
    specs=fullspecs(:,:,:,:,:);
    ppm = in.ppm;

else if npoints ~= 0 && npoints < length(specs)
    ppmmin = ppmmin + (in.ppm(2) -in.ppm(1));
    specs=fullspecs(in.ppm>=ppmmin & in.ppm<=ppmmax,:,:,:,:);
    %calculate the ppm scale
    ppm=in.ppm(in.ppm>=ppmmin & in.ppm<=ppmmax);
else
    %calculate the ppm scale
    ppm=in.ppm(in.ppm>=ppmmin & in.ppm<=ppmmax);
    end
end




%convert back to time domain
%if the length of Fids is odd, then you have to do a circshift of one to
%make sure that you don't introduce a small frequency shift into the fids
%vector.
if mod(size(specs,in.dims.t),2)==0
    %disp('Length of vector is even.  Doing normal conversion');
    fids=ifft(fftshift(specs,in.dims.t),[],in.dims.t);
else
    %disp('Length of vector is odd.  Doing circshift by 1');
    fids=ifft(circshift(fftshift(specs,in.dims.t),1),[],in.dims.t);
end

%calculate the size;
sz=size(fids);


%calculate the new spectral width and dwelltime:
dppm=abs(ppm(2)-ppm(1));
ppmrange=abs((ppm(end)-ppm(1)))+dppm;
spectralwidth=ppmrange*in.Bo*42.577;
dwelltime=1/spectralwidth;

%calculate the time scale
t=[0:dwelltime:(sz(1)-1)*dwelltime];



%FILLING IN DATA STRUCTURE
out=in;
out.fids=fids;
out.specs=specs;
out.sz=sz;
out.ppm=ppm;  
out.t=t; 
out.spectralwidth=spectralwidth;
out.dwelltime=dwelltime;

%FILLING IN THE FLAGS
out.flags=in.flags;
out.flags.writtentostruct=1;
out.flags.freqranged=1;function [MRSCont] = OspreySettings
