end
function [MRSCont] = osp_LoadNII(MRSCont)
%% [MRSCont] = osp_LoadNII(MRSCont)
%   This function reads raw data from NIfTI-MRS files.
%
%   USAGE:
%       [MRSCont] = osp_LoadNII(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2021-07-21)
%       goeltzs1@jhmi.edu
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)


% Close any remaining open figures
close all;
warning('off','all');

%re_mm adding functionality to load MM data
if MRSCont.flags.hasMM 
    if ((length(MRSCont.files_mm) == 1) && (MRSCont.nDatasets(1)>1))   %re_mm seems like specificy one MM file for a batch is also an option to plan to accomodate
        for kk=2:MRSCont.nDatasets(1) %re_mm 
            MRSCont.files_mm{kk} = MRSCont.files_mm{1}; % re_mm allowable to specify one MM file for the whole batch
        end %re_mm 
    end   %re_mm 
    if ((length(MRSCont.files_mm) ~= MRSCont.nDatasets(1)) )   %re_mm 
        msg = 'Number of specified MM files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end   %re_mm 
end   %re_mm 

if MRSCont.flags.hasRef
    if length(MRSCont.files_ref) ~= MRSCont.nDatasets(1)
        msg = 'Number of specified reference files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end
end

if MRSCont.flags.hasWater
    if length(MRSCont.files_w) ~= MRSCont.nDatasets(1)
        msg = 'Number of specified water files does not match number of specified metabolite files.'; %re_mm 
        fprintf(msg);
        error(msg);
    end
end

%% Get the data (loop over all datasets)
refLoadTime = tic;
if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end

for kk = 1:MRSCont.nDatasets(1)
     for ll = 1: 1:MRSCont.nDatasets(2)
        [~] = printLog('OspreyLoad', kk,1, MRSCont.nDatasets ,progressText, MRSCont.flags.isGUI, MRSCont.flags.isMRSI);   
        if ~(MRSCont.flags.didLoad == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'raw') && (kk > length(MRSCont.raw))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)

            % Read in the raw metabolite data.
            metab_ll = MRSCont.opts.MultipleSpectra.metab(ll);
            raw 	= io_loadspec_niimrs(MRSCont.files{metab_ll,kk},MRSCont.opts.load.undoPhaseCycle);
            % Add NIfTI-MRS information
            raw                           = osp_add_nii_mrs_field(raw,MRSCont.ver.Osp);
            % If the sequence flags are not parsed form the nii header
            if sum([raw.flags.isUnEdited raw.flags.isMEGA raw.flags.isHERMES raw.flags.isHERCULES]) == 0
                if MRSCont.flags.isUnEdited
                    raw.flags.isUnEdited = 1;
                end
                if MRSCont.flags.isMEGA
                    raw.flags.isMEGA = 1;
                end
                if MRSCont.flags.isHERMES
                    raw.flags.isHERMES = 1;
                end
                if MRSCont.flags.isHERCULES
                    raw.flags.isHERCULES = 1;
                end
            end

            % Read in the MM data.
            % Leave until we have example data.

            % Read in the raw water reference data.
            if MRSCont.flags.hasRef
                ref_ll = MRSCont.opts.MultipleSpectra.ref(ll);
                raw_ref     = io_loadspec_niimrs(MRSCont.files_ref{ref_ll,kk},MRSCont.opts.load.undoPhaseCycle);
                % If the sequence flags are not parsed form the nii header
                if sum([raw_ref.flags.isUnEdited raw_ref.flags.isMEGA raw_ref.flags.isHERMES raw_ref.flags.isHERCULES]) == 0
                    if MRSCont.flags.isUnEdited
                        raw_ref.flags.isUnEdited = 1;
                    end
                    if MRSCont.flags.isMEGA
                        raw_ref.flags.isMEGA = 1;
                    end
                    if MRSCont.flags.isHERMES
                        raw_ref.flags.isHERMES = 1;
                    end
                    if MRSCont.flags.isHERCULES
                        raw_ref.flags.isHERCULES = 1;
                    end
                end
                % Add NIfTI-MRS information
                raw_ref   = osp_add_nii_mrs_field(raw_ref,MRSCont.ver.Osp);
            end

            % Read in the short-TE water data.
            if MRSCont.flags.hasWater
                w_ll = MRSCont.opts.MultipleSpectra.w(ll);
                raw_w       = io_loadspec_niimrs(MRSCont.files_w{w_ll,kk},MRSCont.opts.load.undoPhaseCycle);
                % If the sequence flags are not parsed form the nii header
                if sum([raw_w.flags.isUnEdited raw_w.flags.isMEGA raw_w.flags.isHERMES raw_w.flags.isHERCULES]) == 0
                    if MRSCont.flags.isUnEdited
                        raw_w.flags.isUnEdited = 1;
                    end
                    if MRSCont.flags.isMEGA
                        raw_w.flags.isMEGA = 1;
                    end
                    if MRSCont.flags.isHERMES
                        raw_w.flags.isHERMES = 1;
                    end
                    if MRSCont.flags.isHERCULES
                        raw_w.flags.isHERCULES = 1;
                    end
                end
                % Add NIfTI-MRS information
                raw_w   = osp_add_nii_mrs_field(raw_w,MRSCont.ver.Osp);
            end





            % Set flag and save data under appropriate name
            if raw.dims.coils == 0
                MRSCont.flags.coilsCombined = 1;

                MRSCont.raw{metab_ll,kk}      = raw;

                if MRSCont.flags.hasRef
                    raw_ref = op_combine_water_subspecs(raw_ref,0);
                    MRSCont.raw_ref{ref_ll,kk}  = raw_ref;
                end

                end
                target1 = MRSCont.opts.editTarget{1};
                target2 = MRSCont.opts.editTarget{2};
                if length(MRSCont.opts.editTarget) > 2
                   target3 = MRSCont.opts.editTarget{3};
                end
                if isfield(MRSCont.opts, 'Order')
                    Order = MRSCont.opts.Order;
                else
                    Order = [];
                end
                [raw, commuteOrder] = osp_onOffClassifyHERMES(raw,[target1 target2],Order);
                raw.commuteOrder = commuteOrder;
                raw.names = {'A', 'B', 'C', 'D'};
                raw.target = MRSCont.opts.editTarget';
                driftPre = driftPre(:,commuteOrder);
                driftPost = driftPost(:,commuteOrder);
                raw.specReg{1}.fs = raw.specReg{1}.fs(:,commuteOrder);
                raw.specReg{1}.phs = raw.specReg{1}.phs(:,commuteOrder);
                raw.specReg{1}.weights = raw.specReg{1}.weights(:,commuteOrder);
                % Save drift information back to container
                MRSCont.QM.drift.pre.A{kk} = driftPre{1};
                MRSCont.QM.drift.pre.B{kk} = driftPre{2};
                MRSCont.QM.drift.pre.C{kk} = driftPre{3};
                MRSCont.QM.drift.pre.D{kk} = driftPre{4};
                MRSCont.QM.drift.post.A{kk} = driftPost{1};
                MRSCont.QM.drift.post.B{kk} = driftPost{2};
                MRSCont.QM.drift.post.C{kk} = driftPost{3};
                MRSCont.QM.drift.post.D{kk} = driftPost{4};
                % Generate the drift plot for the entire experiment in
                % the correct order
                driftPre = [MRSCont.QM.drift.pre.A{kk}, MRSCont.QM.drift.pre.B{kk}, MRSCont.QM.drift.pre.C{kk}, MRSCont.QM.drift.pre.D{kk}]';
                try
                    driftPre = reshape(driftPre, [raw.averages, 1]);
                catch
                    driftPre = reshape(driftPre, [raw.rawAverages, 1]);
                end
                MRSCont.QM.drift.pre.diff1{kk}  = driftPre;
                MRSCont.QM.drift.pre.diff2{kk}  = driftPre;
                if exist('target3', 'var') % For HERMES 4 acqusitions
                    MRSCont.QM.drift.pre.diff3{kk}  = driftPre;
                end
                MRSCont.QM.drift.pre.sum{kk}    = driftPre;
                driftPost = [MRSCont.QM.drift.post.A{kk}, MRSCont.QM.drift.post.B{kk}, MRSCont.QM.drift.post.C{kk}, MRSCont.QM.drift.post.D{kk}]';
                try
                    driftPost = reshape(driftPost, [raw.averages, 1]);
                catch
                    driftPost = reshape(driftPost, [raw.rawAverages, 1]);
                end
                MRSCont.QM.drift.post.diff1{kk}  = driftPost;
                MRSCont.QM.drift.post.diff2{kk}  = driftPost;
                if exist('target3', 'var') % For HERMES 4 acqusitions
                    MRSCont.QM.drift.post.diff3{kk}  = driftPre;
                end
                MRSCont.QM.drift.post.sum{kk}    = driftPost;
            end

%%          %%% 6b. BUILD SUM AND DIFF SPECTRA %%%
            % Correct the frequency axis so that Cr appears at 3.027 ppm
            if raw.flags.isMEGA
                % Create all Hadamard combinations to generate a well defined
                % raw struct
                raw=op_HadamardScans(raw,[-1 1],'diff1');
                raw=op_HadamardScans(raw,[1 1],'sum');
                raw_no_subspec_aling = raw;
                if ~raw.flags.isMRSI
%                     [raw,~]       = op_phaseCrCho(raw, 1);
                    [refShift_SubSpecAlign, ~] = osp_XReferencing(raw,[3.03 3.22],[1 1],[1.85 4.2]);% determine frequency shift
