# Public Diagnostic

Run from this task directory:

```bash
python reproduce.py
```

The Python entrypoint invokes GNU Octave on
`source/sciencebench_task005/task005_public_reproduction.m`. The Octave script
loads the experiment definition from
`fixtures/synthetic_edited_mrs_public.json`, builds that deterministic synthetic
edited-MRS acquisition, writes it through the ordinary SDAT fixture format,
loads it with the candidate source, and measures the common reference signal
before alignment and combination. The JSON fixture is the single source of
truth for the public acquisition parameters.

The report is written to `outputs/reproduction_report.json`. It exposes the
reference-sign consistency and retained common-signal ratio for the scientific
input and the candidate-loaded result. These are observations, not fixed
acceptance values. `workflow_completed` means the real loading path returned a
finite, inspectable edited-MRS result; it does not certify the repair. Private
verification evaluates corrected and intentional polarity-preserving workflows
on additional synthetic spectra and owns the authoritative numerical checks.
Loader, dependency, path, fixture, and report-protocol exceptions are reported
as `runner_failure` with exit code 2 rather than being converted into a
scientific result.
% op_HadamardScans.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_addScans(in1,combMatrix);
% 
% DESCRIPTION:
% Add or subtract two scans together.
% 
% INPUTS:
% in        = Spectrum (in matlab structure format)
% combMatrix	 = How to combine the spectra
%
% OUTPUTS:
% out        = Result of adding inputs in1 and in2.  


function out=op_HadamardScans(in,combMatrix,name);

dim = in.dims.subSpecs;

if ~isempty(fieldnames(in))
    if dim == 2
        if length(combMatrix) == 2
            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2);
        end
        if length(combMatrix) == 4
            fids = combMatrix(1)*in.fids(:,1) + combMatrix(2)*in.fids(:,2) + combMatrix(3)*in.fids(:,3)+ combMatrix(4)*in.fids(:,4);
        end
    end
end

%re-calculate Specs using fft
specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

out=in;
if ~contains(in.names,name)
        out.fids=cat(dim,in.fids,fids);
        out.specs=cat(dim,in.specs,specs);
        out.sz=size(fids);            
        out.names{end+1} = name;
        out.subspecs = out.subspecs + 1;
    else
        ind = find(strcmp(out.names,name));
        out.fids(:,ind,:,:,:,:,:) = fids(:,1,:,:,:,:,:);
        out.specs(:,ind,:,:,:,:,:) = specs(:,1,:,:,:,:,:);
end




% op_preref.m
% USAGE:
% [refShift_ind_ini]=op_preref(in);
% 
% DESCRIPTION:
% We will use a frequency cross-correlation approach on the
% Choline and Creatine singlets to generate a robust initial
% frequency guess for the robust spectral registration. This is
% especially useful for data with heavy frequency drift. The
% transients are averaged into bins including 10% of the
% averages of the whole spectra and referenced afterwards. For
% these packages the same initial frequency guess is forwarded
% to op_robustSpecReg.
% 
% INPUTS:
% in	= input data in matlab structure format.  
%
% OUTPUTS:
% refShift_ind_ini   = Vector with inital frequency shifts
%
%
% AUTHOR:
%       Dr. Helge Zoellner (Johns Hopkins University, 2021-02-11)
%       hzoelln2@jhmi.edu
%
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2021-02-11: First version of the code.
function [refShift_ind_ini]=op_preref(raw,seq,frequencies,polarity,lim,realpart)
if nargin < 7
    realpart =1;
    if nargin < 6
        lim= [0 4.2];
        if nargin < 5
            polarity = [1 1];
            if nargin < 4
                if nargin < 3
                    frequencies = [3.03 3.22];
                    if nargin < 2
                        seq = 'unedited';
                    end
                end
            end
        end
    end
end

% PREPARE DATA
% Based on the sequence type the raw data is split into the sub-spectra.
% Determine the polarity of the respective peak: if the absolute of the
% maximum minus the absolute of the minimum is positive, the polarity 
% of the respective peak is positive; if the absolute of the maximum 
% minus the absolute of the minimum is negative, the polarity is negative.
switch seq
    case 'unedited'
        temp_A = op_averaging(raw);
        raw_A_Cr    = op_freqrange(temp_A,2.8,3.2);
        polResidCr  = abs(max(real(raw_A_Cr.specs))) - abs(min(real(raw_A_Cr.specs)));
        temp_proc = raw;
        if polResidCr < 0        
            temp_proc = op_ampScale(temp_proc,-1);
        end

    case 'MEGA'
        % Get sub-spectra, depending on whether they are stored as such
        if raw.subspecs == 2
            raw_A   = op_takesubspec(raw,1);                    % Get first subspectrum
            raw_B   = op_takesubspec(raw,2);                    % Get second subspectrum
        else
            raw_A   = op_takeaverages(raw,1:2:raw.averages);    % Get first subspectrum
            raw_B   = op_takeaverages(raw,2:2:raw.averages);    % Get second subspectrum
        end

        temp_A = op_averaging(raw_A);
        raw_A_Cr    = op_freqrange(temp_A,2.8,3.2);
        polResidCr  = abs(max(real(raw_A_Cr.specs))) - abs(min(real(raw_A_Cr.specs)));
        temp_rawA = raw_A;
        if polResidCr < 0        
            temp_rawA = op_ampScale(temp_rawA,-1);
        end

        temp_B = op_averaging(raw_B);
        raw_B_Cr    = op_freqrange(temp_B,2.8,3.2);
        polResidCr  = abs(max(real(raw_B_Cr.specs))) - abs(min(real(raw_B_Cr.specs)));
        temp_rawB = raw_B;
        if polResidCr < 0        
            temp_rawB = op_ampScale(temp_rawB,-1);
        end

        temp_proc   = op_addScans(temp_rawA,temp_rawB);

    case {'HERMES','HERCULES'}
        % Get sub-spectra, depending on whether they are stored as such
        if raw.subspecs == 4

            raw_A   = op_takesubspec(raw,1);                    % Get first subspectrum
            raw_B   = op_takesubspec(raw,2);                    % Get second subspectrum
            raw_C   = op_takesubspec(raw,3);                    % Get third subspectrum
            raw_D   = op_takesubspec(raw,4);                    % Get fourth subspectrum

        else

            raw_A   = op_takeaverages(raw,1:4:raw.averages);    % Get first subspectrum
            raw_B   = op_takeaverages(raw,2:4:raw.averages);    % Get second subspectrum
            raw_C   = op_takeaverages(raw,3:4:raw.averages);    % Get third subspectrum
            raw_D   = op_takeaverages(raw,4:4:raw.averages);    % Get fourth subspectrum
        end

        temp_A = op_averaging(raw_A);
        raw_A_Cr    = op_freqrange(temp_A,2.8,3.2);

        polResidCr  = abs(max(real(raw_A_Cr.specs))) - abs(min(real(raw_A_Cr.specs)));
