% op_robustSpecReg.m
% Georg Oeltzschner, Johns Hopkins University 2019.
% Mark Mikkelsen, Johns Hopkins University 2019.
%
% USAGE:
% [out,fs,phs] = op_robustSpecReg(in, seqType, echo, F0, noAlign);
%
% DESCRIPTION:
% Perform robust spectral registration in the time domain to correct frequency and
% phase drifts.
%
% INPUTS:
% in        = Input data structure.
% seqType   = Type of used sequence. Options: 'unedited', 'MEGA', 'HERMES',
%             'HERCULES'
% echo      = Return messages to the prompt? (1 = YES (default), 0 = NO)
%
% OUTPUTS:
% out       = Output following alignment of averages.
% fs        = Vector of frequency shifts (in Hz) used for alignment.
% phs       = Vector of phase shifts (in degrees) used for alignment.
% w         = Vector of relative weights applied to the individual
%             averages.
% F0        = Inital frequency shift guess by cross-correlation (optional)
% noALign   = Flag for switching SpecReg off, while still using the
%             weighted  averaging


function [out, fs, phs, w, driftPre, driftPost] = op_robustSpecReg(in, seqType, echo, F0, noAlign)

if nargin <5
    noAlign = 0;
    if nargin <4
        F0 = nan;
        if nargin < 2
            echo = 1;
        end
    end
end

% Check whether data is coil-combined. If not, throw error.
if ~in.flags.addedrcvrs
    error('ERROR:  I think it only makes sense to do this after you have combined the channels using op_addrcvrs.  ABORTING!!');
end

% Check whether data is averaged. If it is, throw warning and return unmodified data.
if in.dims.averages == 0 || in.averages < 2
    %DO NOTHING
    warning('No averages found.  Returning input without modification!');
    out = in;
    out.flags.freqcorrected = 1;
    fs  = 0;
    phs = 0;
    return
end

% Check whether input structure has sub-spectra.
% If it does, prepare to loop over all sub-spectra. Each sub-spectrum will
% get aligned separately.
if in.dims.subSpecs == 0
    numSubSpecs = 1;
    % Measure drift pre-alignment
    driftPre = op_measureDrift(in);
else
    numSubSpecs = in.sz(in.dims.subSpecs);
    % Measure drift pre-alignment
    for mm = 1:numSubSpecs
        in_sub = op_takesubspec(in, mm);
        driftPre{mm} = op_measureDrift(in_sub);
    end
end

% Pre-allocate memory.
fs      = zeros(in.sz(in.dims.averages),numSubSpecs);
phs     = zeros(in.sz(in.dims.averages),numSubSpecs);
fids    = zeros(in.sz(in.dims.t),1,numSubSpecs);
runCount = 0;

% Optimization options
lsqnonlinopts = optimoptions(@lsqnonlin);
lsqnonlinopts = optimoptions(lsqnonlinopts,'Display','off','Algorithm','levenberg-marquardt');

% Initialize common variables and loop over sub-spectra
t                 = in.t;
input.dwelltime   = in.dwelltime;

for mm=1:numSubSpecs

        %%% Automatic lipid/unstable residual water removal %%%
        freq        = in.ppm;
        waterLim = freq <= 4.68 + 0.25 & freq >= 4.68 - 0.25;
        lipidLim = freq <= 1.85 & freq >= 0;
        noiseLim = freq <= 11 & freq >= 10;

        % Create a lipid-to-noise criterion from the mean unaligned data
        S = mean(in.specs(:,:,mm), 2);
        r = std(S(lipidLim)) / std(S(noiseLim));
        r_threshold = 40;
        % Create a 'how unstable is the residual water signal?' criterion from
        % the mean unaligned data
        q = sum(abs(in.specs(waterLim,:,mm))) * abs(freq(1) - freq(2));
        q = q / max(q);
        q = sum(q < 0.5) / length(q);
        q_threshold = 0.1;

        % If significant lipid signal and/or unstable residual water signal is
        % present, run the Whittaker filtering in the frequency domain.
        lipid_flag = 0;
        water_flag = 0;
        if r > r_threshold || q > q_threshold
            % Extract the frequency-domain sub-spectrum
            spec = in.specs(:,:,mm);

            % Is there excessive lipid?
            if r > r_threshold
                lipid_flag = 1;
            end
            % Is there unstable residual water?
            if q > q_threshold
                water_flag = 1;
            end

            reverseStr = '';

            % Loop over averages in the sub-spectrum
            for jj = 1:in.sz(in.dims.averages)

                if echo
                    if lipid_flag && ~water_flag
                        msg = sprintf('\nLipid contamination detected. Applying lipid filter to transient: %d\n', jj);
                    elseif ~lipid_flag && water_flag
                        msg = sprintf('\nUnstable residual water detected. Applying residual water filter to transient: %d\n', jj);
                    elseif lipid_flag && water_flag
                        msg = sprintf('\nLipid contamination and unstable residual water detected. Applying lipid and residual water filters to transient: %d\n', jj);
                    end
                    fprintf([reverseStr, msg]);
                    reverseStr = repmat(sprintf('\b'), 1, length(msg));
                end

                DataToAlign(:,jj) = SignalFilter(spec(:,jj), lipid_flag, water_flag, in);

            end

            if ishandle(77)
                close(77);
            end

        else

            DataToAlign = in.fids(:,:,mm);

% op_eccKlose.m
% Jamie Near, McGill University 2014.
% Georg Oeltzschner, Johns Hopkins University 2019.
% 
% USAGE:
% [out,outw]=op_eccKlose(in,inw);
% 
% DESCRIPTION:
% Perform a classic Klose eddy current correction (Klose, Magn Reson Med
% 14:26-30 (1990). The complex signal vector of the water-suppressed FID is
% divided by the phase vector of the water-unsuppressed FID. Both
% acquisitions need to be performed with identical gradient strenghts and 
% timing, so that the eddy current behavior is the same in both. 
% 
% INPUTS:
% in     = water suppressed input data in matlab structure format.
% inw    = water unsuppressed input data in matlab structure format.
%
% OUTPUTS:
% out    = Water suppressed output following eddy current correction  
% outw   = Water unsuppressed output following eddy current correction

function [out,outw]=op_eccKlose(in,inw)
if inw.dims.coils~=0 ||  inw.dims.subSpecs~=0 || inw.averages>1
    if inw.subspecs > 1
        inw_A               = op_takesubspec(inw,1);
        [inw_A]             = op_rmempty(inw_A);            % Remove empty lines
        inw_B               = op_takesubspec(inw,2);
        [inw_B]             = op_rmempty(inw_B);            % Remove empty lines
        inw                 = op_concatAverages(inw_A,inw_B);            
    end
    if ~inw.flags.averaged
        [inw]             = op_rmempty(inw); 
        [inw,~,~]           = op_alignAverages(inw,1,'n');  % Align averages
        inw                 = op_averaging(inw);            % Average
    end
end

% Determine the phase of the complex water FID.
inph=unwrap(angle(inw.fids));

% Now apply the eddy current correction to both the water-suppressed and the
% water-unsuppressed data:
out=in;
out.phase_ecc = inph;
if in.te == inw.te   
    out.fids=out.fids.*exp(1i*-inph);
    out.specs=fftshift(fft(out.fids,[],1),1);          
end

% Add NIfTI-MRS provenance
% Generate fields for provenance
fields.Method   = 'Eddy current correction';
fields.Details  = ['ECC (Klose 1990), reference = raw_ref'];
out = op_add_analysis_provenance(out,fields);

outw=inw;
outw.phase_ecc = inph;
outw.fids=outw.fids.*exp(1i*-inph);
outw.specs=fftshift(fft(outw.fids,[],1),1);

% Add NIfTI-MRS provenance
% Generate fields for provenance
fields.Method   = 'Eddy current correction';
fields.Details  = ['ECC (Klose 1990), reference = raw_ref'];
outw = op_add_analysis_provenance(outw,fields);

function [out] = op_combine_water_subspecs(in,average)
% Some formats end up having subspectra in their reference scans
% (e.g. Philips), as well as empty lines. Intercept these cases
% here.
if nargin < 2
    average = 1;
end
    out = in;
    if out.subspecs == 2
        raw_A               = op_takesubspec(out,1);
        [raw_A]             = op_rmempty(raw_A);            % Remove empty lines
        raw_B               = op_takesubspec(out,2);
        [raw_B]             = op_rmempty(raw_B);            % Remove empty lines
        out                 = op_concatAverages(raw_A,raw_B);
    end

    if out.subspecs == 4
        raw_A               = op_takesubspec(out,1);
        [raw_A]             = op_rmempty(raw_A);            % Remove empty lines
        raw_B               = op_takesubspec(out,2);
        [raw_B]             = op_rmempty(raw_B);            % Remove empty lines
        raw_C               = op_takesubspec(out,3);
        [raw_C]             = op_rmempty(raw_C);            % Remove empty lines
        raw_D               = op_takesubspec(out,4);
        [raw_D]             = op_rmempty(raw_D);            % Remove empty lines
        out                 = op_concatAverages(op_concatAverages(raw_A,raw_B),op_concatAverages(raw_C,raw_D));
    end
    if out.subspecs == 1
        [out]             = op_rmempty(out);            % Remove empty lines
    end
    if average
        % Align and verage the refernce data
        if out.averages > 1 && ~out.flags.averaged
            [out]             = op_rmempty(out);
            [out,~,~]               = op_alignAverages(out, 1, 'n');
            out                     = op_averaging(out);            % Average
        else
            out.flags.averaged  = 1;
            out.dims.averages   = 0;
        end
    end
    out.names = {'A'};
end% op_averaging.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_averaging(in);
% 
% DESCRIPTION:
% Combine the averages in a scan by adding the averages together and then 
% dividing by the number of averages.
% 
% INPUTS:
% in	= input data in matlab structure format.
%
% OUTPUTS:
% out   = Output following averaging.  

function out=op_averaging(in);

if in.flags.averaged
    error('ERROR:  Averaging has already been performed!  Aborting!');
end

if in.dims.averages==0 || in.averages<2 || (length(in.sz)< in.dims.averages)
    %DO NOTHING
    warning('Just one average found. Returning input without modification!');
    %change the dims variables.
    dims.t=in.dims.t;
    if in.dims.coils>in.dims.averages
        dims.coils=in.dims.coils-1;
    else
        dims.coils=in.dims.coils;
    end
    dims.averages=0;
    if in.dims.subSpecs>in.dims.averages
        dims.subSpecs=in.dims.subSpecs-1;
    else
        dims.subSpecs=in.dims.subSpecs;
    end
    if in.dims.extras>in.dims.averages
        dims.extras=in.dims.extras-1;
    else
        dims.extras=in.dims.extras;
    end
    out=in;
    out.dims=dims;
    out.flags.averaged=1;
else

    %add the spectrum along the averages dimension;
    fids=sum(in.fids,in.dims.averages);
    fids=squeeze(fids);
    fids=fids/in.sz(in.dims.averages); %divide by number of averages;

    %re-calculate Specs using fft
    specs=fftshift(fft(fids,[],in.dims.t),in.dims.t);

    %change the dims variables.
    if in.dims.t>in.dims.averages
        dims.t=in.dims.t-1;
    else
        dims.t=in.dims.t;
    end
    if in.dims.coils>in.dims.averages
        dims.coils=in.dims.coils-1;
    else
        dims.coils=in.dims.coils;
    end
    dims.averages=0;
    if in.dims.subSpecs>in.dims.averages
        dims.subSpecs=in.dims.subSpecs-1;
    else
        dims.subSpecs=in.dims.subSpecs;
    end
    if in.dims.extras>in.dims.averages
        dims.extras=in.dims.extras-1;
    else
        dims.extras=in.dims.extras;
    end


    %re-calculate the sz variable
    sz=size(fids);

    % Add NIfTI-MRS provenance
    % Generate fields for provenance
    fields.Method   = 'Signal averaging';
    fields.Details  = ['Classic signal averaging, dim = DIM_DYN'];
    in = op_add_analysis_provenance(in,fields);

    %FILLING IN DATA STRUCTURE
    out=in;
    out.fids=fids;
    out.specs=specs;
    out.sz=sz;
    out.dims=dims;
    out.averages=1;

    %FILLING IN THE FLAGS
    out.flags=in.flags;
    out.flags.writtentostruct=1;
    out.flags.averaged=1;

end



