function polarity = op_getSpectralPolarity(in, ppmmin, ppmmax)
% Estimate one polarity per subspectrum from a common reporter peak.
% Average any remaining dimensions before comparing positive and negative
% extrema. Empty ranges and tied/zero extrema do not justify a sign change.

if in.dims.subSpecs > 0
    nSubspecs = size(in.specs, in.dims.subSpecs);
else
    nSubspecs = 1;
end
polarity = ones(1, nSubspecs);
mask = in.ppm >= ppmmin & in.ppm <= ppmmax;
if ~any(mask)
    return;
end

indices = repmat({':'}, 1, ndims(in.specs));
indices{in.dims.t} = mask;
order = [in.dims.t setdiff(1:ndims(in.specs), in.dims.t)];
for ss = 1:nSubspecs
    if in.dims.subSpecs > 0
        indices{in.dims.subSpecs} = ss;
    end
    spec = permute(in.specs(indices{:}), order);
    spec = real(mean(reshape(spec, sum(mask), []), 2));
    if -min(spec) > max(spec)
        polarity(ss) = -1;
    end
end
end
% op_ampScale.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_ampScale(in,A);
% 
% DESCRIPTION:
% Scale the amplitude of a spectrum by factor A.
% 
% INPUTS:
% in    = input data in matlab structure format
% A     = Scalar amplitude scaling factor, or one factor per subspectrum.
%
% OUTPUTS:
% out   = Output following amplitude scaling.  

function out=op_ampScale(in,A);

out=in;
if isscalar(A)
    out.specs=in.specs.*A;
    out.fids=in.fids.*A;
else
    dim = in.dims.subSpecs;
    if dim == 0 || ~isvector(A) || numel(A) ~= size(in.fids, dim)
        error('op_ampScale:InvalidScale', 'Supply a scalar or one amplitude factor per subspectrum.');
    end
    scaleSize = ones(1, ndims(in.fids));
    scaleSize(dim) = numel(A);
    A = reshape(A, scaleSize);
    out.specs = bsxfun(@times, in.specs, A);
    out.fids = bsxfun(@times, in.fids, A);
end
