    dataSize = size(data);
    if mod(dataSize(2), subspecs) ~= 0
        error('io_loadspec_sdat:InvalidRows', 'The number of rows must be divisible by the number of subspectra.');
    end
    % Interleaved rows become samples-averages-subspectra, retaining any
    % remaining dimensions and singleton averages.
    fids = reshape(data, [dataSize(1) subspecs dataSize(2)/subspecs dataSize(3:end)]);
    fids = permute(fids, [1 3 2 4:ndims(fids)]);
    if dims.extras > 2
        dims.extras = dims.extras + 1;
    end
    if isfield(dims, 'Zvoxels') && dims.Zvoxels > 2
