    corrph = ones(size(firstPoint));
    valid = isfinite(firstPoint) & abs(firstPoint) > 0;
    corrph(valid) = conj(firstPoint(valid)) ./ abs(firstPoint(valid));
    fids = reshape(bsxfun(@times, fids, corrph), fidSize);
